import { NextResponse } from 'next/server';
import nodemailer from 'nodemailer';

export async function POST(request: Request) {
  try {
    const { to, subject, html, text } = await request.json();

    if (!to) {
      return NextResponse.json(
        { error: "Recipient email 'to' is required." },
        { status: 400 }
      );
    }

    // specific check for credentials
    const smtpUser = process.env.SMTP_USER;
    const smtpPass = process.env.SMTP_PASS;
    const smtpHost = process.env.SMTP_HOST || 'smtp.gmail.com';
    const smtpPort = parseInt(process.env.SMTP_PORT || '587');

    // If credentials are missing, we can't actually send, but we can simulate success for dev
    // or return an error telling the user to configure them. 
    // Given the user wants it to "work", let's try to send, and if it fails, catch it.
    // However, without credentials, nodemailer verify will fail.
    
    if (!smtpUser || !smtpPass) {
        console.log("Mock Email Send (Missing Credentials):");
        console.log("To:", to);
        console.log("Subject:", subject);
        console.log("Content:", text || html);
        return NextResponse.json({ 
            success: true, 
            message: "Email logged to server console (SMTP credentials missing). Check .env.local to configure real sending." 
        });
    }

    const transporter = nodemailer.createTransport({
      host: smtpHost,
      port: smtpPort,
      secure: smtpPort === 465, // true for 465, false for other ports
      auth: {
        user: smtpUser,
        pass: smtpPass,
      },
    });

    await transporter.sendMail({
      from: process.env.SMTP_FROM || '"AI Finance" <no-reply@example.com>',
      to,
      subject,
      text, // plain text body
      html, // html body
    });

    return NextResponse.json({ success: true, message: "Email sent successfully" });

  } catch (error: any) {
    console.error("Error sending email:", error);
    return NextResponse.json(
      { error: "Failed to send email", details: error.message },
      { status: 500 }
    );
  }
}
